export function Button({ variant, size, ...rest }: ButtonProps) {
  return (
    <button
      className={cx("btn", variant, size)}
      {...rest}
    />
  );
}

export function TextField({ label, value, onChange, hint }: TextFieldProps) {
  return (
    <label className="field">
      <span>{label}</span>
      <input className="input" value={value}
        onChange={(e) => onChange(e.target.value)} />
    </label>
  );
}

export function Chip({ tone = "neutral", color, dot, children }: ChipProps) {
  if (color) return <span style={mix(color)}>{children}</span>;
  return <span className={`chip tone-${tone}`}>{children}</span>;
}

import { GraphCanvas, ZoomControls } from "@/shared/ui/layouts/GraphCanvas";
import { useGraphViewport } from "@/shared/ui/layouts/useGraphViewport";

const vp = useGraphViewport(world);
<GraphCanvas vp={vp} world={world} grid
  toolbar={<ZoomControls vp={vp}/>}>
  {edges}{nodes}
</GraphCanvas>

import { PaneGrid } from "@/shared/ui/layouts/PaneGrid";

<PaneGrid cols={2} rows={2}>
  {panes.map((p) => <Pane key={p.id} {...p}/>)}
</PaneGrid>
